rules.bad:
try {
  syncData();
} catch (Exception e) {
  // 什么都没做
}

try {
  parseJson(s);
} catch (Exception e) {
  e.printStackTrace();   // 打印后继续，同样等于吞掉
}

rules.good:
try {
  syncData();
} catch (Exception e) {
  log.error("同步数据失败, taskId={}", taskId, e);
  throw new BizException(ErrorCode.SYNC_FAILED, "同步数据失败", e);
}

// 确实可忽略时，必须写注释
try {
  num = Integer.parseInt(s);
} catch (NumberFormatException e) {
  // s 可能不是数字，此处回退为默认值 0，属于预期分支
  num = 0;
}

rules.bad:
try {
  if (!checkQuota(id)) throw new QuotaException();
  doWork();
} catch (QuotaException e) {
  return "配额不足";
}

try {
  return calc();
} finally {
  return null;   // try 的返回值被丢弃
}

InputStream in = null;
try {
  in = new FileInputStream(f);
  read(in);
} finally {
  if (in != null) in.close();   // close 抛异常会覆盖真实异常
}

rules.good:
log.info("查询用户: {}, 结果: {}", userId, user);
if (log.isDebugEnabled()) {
  log.debug("payload = {}", JSON.toJSONString(obj));
}

rules.bad:
catch (Exception e) {
  log.error("保存失败: " + e.getMessage());   // 无堆栈、无现场
}

rules.good:
catch (Exception e) {
  log.error("保存订单失败, userId={}, orderNo={}", userId, orderNo, e);   // 异常作为最后一个参数
}

